"use client";

import { create } from "zustand";
import { persist } from "zustand/middleware";
import type { CVData } from "@/lib/cv/schema";
import { appendHistory, type ScorePoint } from "@/lib/ai/simulateImpact";

/**
 * Persisted "target" benchmark (req 20, reframed).
 *
 * The ideal CV generated by Simulate is SYNTHETIC — a ~100% match for a job
 * description, never the user's facts. Instead of discarding it after a one-shot
 * gap report, we persist it as a target the user edits against: the Target page
 * renders it side-by-side with the live CV and re-rates the match on every edit.
 *
 * This is a reference only. It must never be merged into the real CV or exported
 * as the user's own.
 */
export interface SavedTarget {
  id: string;
  ideal: CVData;
  jd: string;
  idealJd: string;
  label: string;
  createdAt: number | null;
  baseScore: number;
  history: ScorePoint[];
}

const MAX_SAVED = 4;

interface TargetState {
  /** The simulated ideal CV, or null when no target is locked. */
  ideal: CVData | null;
  /** The job description the ideal was generated from. */
  jd: string;
  /** The JD the current ideal was simulated from; differs from `jd` once the
   *  shared JD is edited (in Refine or Simulate), meaning the ideal is stale. */
  idealJd: string;
  /** Short label for the role (derived from the ideal's title/JD) for the UI. */
  label: string;
  /** Epoch ms the target was set; null when unset. */
  createdAt: number | null;
  /** Match score of the user's CV at the moment the target was locked. */
  baseScore: number;
  /** True after a refine was applied while a target is locked: Simulate should
   *  offer to re-run against the new CV and (confirmed) JD. */
  resimPrompt: boolean;
  /** Match score over time (deduped, capped) for the verdict sparkline. */
  history: ScorePoint[];
  /** Other targets the user has benchmarked against; the active one is the flat fields. */
  saved: SavedTarget[];

  switchTarget: (id: string) => void;
  removeSaved: (id: string) => void;
  recordScore: (score: number) => void;
  setJd: (jd: string) => void;
  setTarget: (ideal: CVData, jd: string, baseScore: number, label?: string) => void;
  clearTarget: () => void;
  /** User-initiated "Clear target": drops the ideal but keeps the shared JD so
   *  Refine's job description isn't lost. Account wipes use `clearTarget`. */
  discardTarget: () => void;
  requestResim: () => void;
  dismissResim: () => void;
}

/** Derive a compact role label from the ideal CV / JD for display. */
function deriveLabel(ideal: CVData, jd: string): string {
  const t = ideal.basics.title?.trim();
  if (t) return t;
  const firstLine = jd.trim().split(/\r?\n/)[0]?.trim() ?? "";
  if (firstLine) return firstLine.slice(0, 60);
  return "Target role";
}

function snapshot(s: TargetState): SavedTarget {
  return {
    id: `${s.createdAt ?? 0}-${s.label}`,
    ideal: s.ideal as CVData, jd: s.jd, idealJd: s.idealJd, label: s.label,
    createdAt: s.createdAt, baseScore: s.baseScore, history: s.history ?? [],
  };
}

export const useTargetStore = create<TargetState>()(
  persist(
    (set) => ({
      ideal: null,
      jd: "",
      idealJd: "",
      label: "",
      createdAt: null,
      baseScore: 0,
      resimPrompt: false,
      history: [],
      saved: [],

      switchTarget: (id) =>
        set((s) => {
          const next = s.saved.find((t) => t.id === id);
          if (!next) return {};
          const rest = s.saved.filter((t) => t.id !== id);
          const current = s.ideal ? [snapshot(s)] : [];
          return {
            ideal: next.ideal, jd: next.jd, idealJd: next.idealJd, label: next.label,
            createdAt: next.createdAt, baseScore: next.baseScore, history: next.history,
            resimPrompt: false, saved: [...rest, ...current].slice(-MAX_SAVED),
          };
        }),
      removeSaved: (id) => set((s) => ({ saved: s.saved.filter((t) => t.id !== id) })),

      recordScore: (score) =>
        set((s) => {
          if (!s.ideal) return {};
          const next = appendHistory(s.history ?? [], score, Date.now());
          return next === s.history ? {} : { history: next };
        }),
      setJd: (jd) => set({ jd }),

      setTarget: (ideal, jd, baseScore, label) =>
        set((s) => {
          const nextLabel = label?.trim() || deriveLabel(ideal, jd);
          const kept = s.saved.filter((t) => t.label !== nextLabel);
          const stash = s.ideal && s.label !== nextLabel ? [snapshot(s)] : [];
          return {
          saved: [...kept, ...stash].slice(-MAX_SAVED),
          ideal,
          jd,
          idealJd: jd,
          baseScore,
          label: nextLabel,
          createdAt: Date.now(),
          resimPrompt: false,
          history: [{ t: Date.now(), score: baseScore }],
          };
        }),

      discardTarget: () => set({ ideal: null, idealJd: "", label: "", createdAt: null, baseScore: 0, resimPrompt: false, history: [] }),
      clearTarget: () => set({ saved: [], ideal: null, jd: "", idealJd: "", label: "", createdAt: null, baseScore: 0, resimPrompt: false, history: [] }),
      requestResim: () => set((s) => (s.ideal ? { resimPrompt: true } : {})),
      dismissResim: () => set({ resimPrompt: false }),
    }),
    {
      // Anonymous default; StorageScope rebinds per signed-in user id.
      name: "orire-target:anon:v1",
      partialize: (s) => ({ ideal: s.ideal, jd: s.jd, idealJd: s.idealJd, label: s.label, createdAt: s.createdAt, baseScore: s.baseScore, resimPrompt: s.resimPrompt, history: s.history, saved: s.saved }),
    },
  ),
);

/** True when a target is locked but the shared JD has since been edited. Older
 *  persisted targets have no `idealJd`, so they are never flagged. */
export function isIdealStale(s: Pick<TargetState, "ideal" | "jd" | "idealJd">): boolean {
  return Boolean(s.ideal && s.idealJd && s.idealJd.trim() !== s.jd.trim());
}
